    for r in range(rows):
        for c in range(cols):
            dfs(r, c, trie)
    return list(res)

def generate_parenthesis(n):
    res = []
    def backtrack(s, o, c):
        if len(s) == 2 * n:
            res.append(s)
            return
        if o < n:
            backtrack(s + '(', o + 1, c)
        if c < o:
            backtrack(s + ')', o, c + 1)
    backtrack('', 0, 0)
    return res

def word_break(s, wordDict):
    words = set(wordDict)
    dp = [False] * (len(s) + 1)
    dp[0] = True
    for i in range(1, len(s) + 1):
        for w in words:
            if i >= len(w) and dp[i - len(w)] and s[i-len(w):i] == w:
                dp[i] = True
                break
    return dp[len(s)]

def climb_stairs(n):
