        self.time = 0
        self.tweets = {}
        self.following = {}
    def postTweet(self, userId, tweetId):
        self.time += 1
        self.tweets.setdefault(userId, []).append((-self.time, tweetId))
    def getNewsFeed(self, userId):
        users = {userId} | self.following.get(userId, set())
        feed = []
        for u in users:
            feed.extend(self.tweets.get(u, [])[:10])
        heapq.heapify(feed)
        return [tid for _, tid in heapq.nsmallest(10, feed)]
