def group_anagrams(words):
    from collections import defaultdict
    m = defaultdict(list)
    for w in words:
        m["".join(sorted(w))].append(w)
    return sorted((sorted(v) for v in m.values()), key=lambda g: g[0])

def longest_consecutive(nums):
    s = set(nums)
    best = 0
    for x in s:
        if x - 1 not in s:
            cur, ln = x, 1
            while cur + 1 in s:
                cur += 1
                ln += 1
            best = max(best, ln)
    return best

def top_k_frequent(nums, k):
