class TrieNode:
    def __init__(self):
        self.children = {}
        self.end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.end = True
    def search(self, word):
        node = self._find(word)
        return bool(node and node.end)
    def startsWith(self, prefix):
        return self._find(prefix) is not None
    def _find(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

def generate_parenthesis(n):
    res = []
    def backtrack(s, o, c):
        if len(s) == 2 * n:
            res.append(s)
            return
        if o < n:
            backtrack(s + '(', o + 1, c)
        if c < o:
            backtrack(s + ')', o, c + 1)
    backtrack('', 0, 0)
    return res

