import sys, json

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for c in word:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
        node.is_end = True
    def search(self, word):
        node = self.root
        for c in word:
            if c not in node.children:
                return False
            node = node.children[c]
        return node.is_end
    def startsWith(self, prefix):
        node = self.root
        for c in prefix:
            if c not in node.children:
                return False
            node = node.children[c]
        return True

def main():
    data = sys.stdin.read().strip()
    ops = json.loads(data.split("ops = ", 1)[1].split("\n")[0].strip())
    args = json.loads(data.split("args = ", 1)[1].strip())
    trie = Trie()
    results = [None]
    for i in range(1, len(ops)):
        if ops[i] == 'insert':
            trie.insert(args[i][0])
            results.append(None)
        elif ops[i] == 'search':
            results.append(trie.search(args[i][0]))
        elif ops[i] == 'startsWith':
            results.append(trie.startsWith(args[i][0]))
    print(results)

main()

import sys, json

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class WordDictionary:
    def __init__(self):
        self.root = TrieNode()
    def addWord(self, word):
        node = self.root
        for c in word:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
        node.is_end = True
    def search(self, word):
        def dfs(node, idx):
            if idx == len(word):
                return node.is_end
            c = word[idx]
            if c == '.':
                for child in node.children.values():
                    if dfs(child, idx + 1):
                        return True
                return False
            if c not in node.children:
                return False
            return dfs(node.children[c], idx + 1)
        return dfs(self.root, 0)

def main():
    data = sys.stdin.read().strip()
    ops_line = data.split("\n")[0]
    args_line = data.split("\n")[1]
    ops = json.loads(ops_line.split(" = ", 1)[1])
    args = json.loads(args_line.split(" = ", 1)[1])
    wd = WordDictionary()
    results = [None]
    for i in range(1, len(ops)):
        if ops[i] == 'addWord':
            wd.addWord(args[i][0])
            results.append(None)
        elif ops[i] == 'search':
            results.append(wd.search(args[i][0]))
    print(results)

